//! Embedder Impact Benchmark CLI //! //! Measures each embedder's contribution to: //! - Retrieval quality (MRR, P@K, R@K, NDCG) //! - Knowledge graph structure //! - Resource usage //! //! # Usage //! //! ```bash //! # Quick benchmark (Tier 1) //! cargo run -p context-graph-benchmark --bin embedder-impact-bench -- --tier 1 //! //! # Standard benchmark with markdown output //! cargo run -p context-graph-benchmark --bin embedder-impact-bench -- \ //! --tier 2 --format markdown --output docs/EMBEDDER_IMPACT.md //! //! # Comprehensive benchmark //! cargo run -p context-graph-benchmark --bin embedder-impact-bench -- \ //! --tier 2 --components all --format markdown //! ``` use std::fs; use std::io::Write; use std::path::PathBuf; use clap::Parser; use tracing_subscriber::EnvFilter; use context_graph_benchmark::datasets::graph_linking::ScaleTier; use context_graph_benchmark::metrics::causal::E5ImpactAnalysis; use context_graph_benchmark::runners::embedder_impact::{ EmbedderImpactConfig, EmbedderImpactResults, EmbedderImpactRunner, RecommendationType, }; use context_graph_storage::teleological::indexes::EmbedderIndex; /// Embedder Impact Benchmark CLI #[derive(Parser, Debug)] #[command(name = "embedder-impact-bench")] #[command(about = "Benchmark per-embedder contribution to retrieval quality")] struct Args { /// Tier level (1-6): 1=100, 2=1K, 3=10K, 4=100K, 5=1M, 6=10M #[arg(short, long, default_value = "1")] tier: u8, /// Additional tiers to run (comma-separated) #[arg(long, value_delimiter = ',')] extra_tiers: Option<Vec<u8>>, /// Components to benchmark: retrieval, graph, resource, all #[arg(short, long, default_value = "retrieval")] components: String, /// Output format: table, json, markdown #[arg(short, long, default_value = "table")] format: String, /// Output file path (stdout if not specified) #[arg(short = 'O', long)] output: Option<PathBuf>, /// Random seed #[arg(short, long, default_value = "42")] seed: u64, /// Top K for retrieval #[arg(short = 'k', long, default_value = "10")] top_k: usize, /// Verbose output #[arg(short, long)] verbose: bool, } fn main() -> anyhow::Result<()> { // Parse args let args = Args::parse(); // Setup logging let filter = if args.verbose { EnvFilter::new("debug") } else { EnvFilter::new("info") }; tracing_subscriber::fmt() .with_env_filter(filter) .with_target(false) .init(); // Build tier list let mut tiers = vec![ScaleTier::from_level(args.tier)?]; if let Some(extra) = &args.extra_tiers { for &level in extra { tiers.push(ScaleTier::from_level(level)?); } } // Parse components let run_graph = args.components == "graph" || args.components == "all"; let run_resource = args.components == "resource" || args.components == "all"; // Build config let config = EmbedderImpactConfig { tiers, queries_per_tier: None, k_values: vec![1, 5, 10, 20], seed: args.seed, run_blind_spot_analysis: true, run_graph_impact: run_graph, run_resource_analysis: run_resource, embedders: context_graph_benchmark::ablation::all_core_embedders(), baseline_embedder: EmbedderIndex::E1Semantic, min_similarity: 0.0, top_k: args.top_k, }; tracing::info!("Starting embedder impact benchmark"); tracing::info!("Tiers: {:?}", config.tiers); // Run benchmark let mut runner = EmbedderImpactRunner::new(config); let results = runner.run(); tracing::info!("Benchmark completed in {}ms", results.metadata.duration_ms); // Format output let output = match args.format.as_str() { "json" => format_json(&results)?, "markdown" => format_markdown(&results), _ => format_table(&results), }; // Write output if let Some(path) = args.output { let mut file = fs::File::create(&path)?; file.write_all(output.as_bytes())?; tracing::info!("Results written to {}", path.display()); } else { println!("{}", output); } // Print compliance summary if !results.compliance.is_compliant { tracing::warn!("Constitutional compliance issues detected:"); for note in &results.compliance.notes { tracing::warn!(" - {}", note); } } Ok(()) } fn format_json(results: &EmbedderImpactResults) -> anyhow::Result<String> { Ok(serde_json::to_string_pretty(results)?) } fn format_table(results: &EmbedderImpactResults) -> String { let mut out = String::new(); out.push_str("
